#include <Wire.h>
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C LCD = LiquidCrystal_I2C(0x27, 16, 2);

#define I2C_SDA 5
#define I2C_SCL 4

void setup() {
  Serial.begin(115200);
  Wire.begin(I2C_SDA, I2C_SCL);
  LCD.init();
  LCD.backlight();
  LCD.setCursor(6, 0);
  LCD.print("TTTT");
}
void loop() {}
